import{_ as t,o,c as d,O as r}from"./app.3bbb2247.js";const u='{"title":"useDrop","description":"","frontmatter":{},"headers":[{"level":2,"title":"parameters","slug":"parameters"},{"level":2,"title":"return value","slug":"return-value"},{"level":3,"title":"Specification object","slug":"specification-object"}],"relativePath":"en/guide/composition/use-drop.md"}',c={};function n(i,e,a,s,h,l){return o(),d("div",null,e[0]||(e[0]=[r('<h3 id="specification-object" tabindex="-1">Specification object <a class="header-anchor" href="#specification-object" aria-hidden="true">#</a></h3><p>Before understanding the basic usage of the <code>Specification</code> object, you may need to understand the <a href="./../monitors/drop-target-monitor.html">DropTargetMonitor</a> object.</p><table><thead><tr><th>Key</th><th>Required</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>accept</td><td>yes</td><td><code>string | symbol | string[] | symbol[]</code></td><td>This drop target will only react to <a href="./use-drag.html">a drag source of the specified type</a>.</td></tr><tr><td>collect</td><td>no</td><td><code>(monitor: DropTargetMonitor) =&gt; CollectedProps</code></td><td>A function for a collector. It should return a plain object and be the first item in the return value of <code>useDrop</code>.</td></tr><tr><td>options</td><td>no</td><td><code>object</code></td><td>currently useless.</td></tr><tr><td>drop</td><td>no</td><td><code>(item: object, monitor: DropTargetMonitor) =&gt; (void | Record&lt;string, any&gt;)</code></td><td>Called when the drop element is dropped on the target. <br>You can return nothing, or you can return a plain object. <br>If you return an object, it becomes <code>dropResult</code>, and in the <code>end</code> method of <code>drag</code>, it can be obtained by <code>monitor.getDropResult()</code>. This is a good choice if you want to perform different actions based on different drop targets. <br>If your drop target is nested, then you can check if the nested target has been processed with <code>monitor.didDrop()</code> and <code>monitor.getDropResult()</code>. <br>This method, along with the <code>end</code> method of <code>drag</code>, is a good place to handle data changes. This method will not be called if the <code>canDrop()</code> method returns <code>false</code>.</td></tr><tr><td>hover</td><td>no</td><td><code>(item: object, monitor: DropTargetMonitor) =&gt; void </code></td><td>This method is called when the dragged component passes over the component. <br>You can check if the hover is only happening on the current target or on the inner nested target by checking <code>monitor.isOver({ shallow: true })</code>. <br>The difference from the <code>drop()</code> method is that this method will be called even if <code>canDrop()</code> returns <code>false</code>. <br>You can confirm and avoid this with <code>monitor.canDrop()</code>.</td></tr><tr><td>canDrop</td><td>no</td><td><code>(item: DragObject, monitor: DropTargetMonitor&lt;DragObject, DropResult&gt;) =&gt; boolean</code></td><td>Use it to specify whether the drop target is able to accept the item. <br>If you want to always allow it, omit this method. <br>Specifying it is handy if you&#39;d like to disable dropping based on some predicate over <code>props</code> or <code>monitor.getItem()</code>. <br>Note: You may not call <code>monitor.canDrop()</code> inside this method.</td></tr></tbody></table>',3)]))}var m=t(c,[["render",n]]);export{u as __pageData,m as default};
